const data = $input.item.json.data;
let clientText = 'Ось 3 найкращі варіанти квартир з нашої бази:\n\n';
let managerText = '';

if (data && data.length > 0) {
  for (let i = 0; i < Math.min(3, data.length); i++) {
    const item = data[i];
    clientText += `${i+1}. ${item.title}\n💰 Ціна: ${item.params.find(p => p.key === 'price')?.value?.label || 'Не вказана'}\n📍 Район: ${item.location.city.name}\n\n`;
    managerText += `${i+1}. ${item.url}\n`;
  }
  clientText += 'Якщо вам подобається якийсь із цих варіантів, напишіть його номер сюди, і наш менеджер організує перегляд!';
} else {
  clientText = 'На жаль, за вашими критеріями зараз немає вільних квартир. Менеджер зв\'яжеться з вами, щоб запропонувати інші варіанти.';
  managerText = 'Не знайдено результатів';
}

return {
  clientText: clientText,
  managerText: managerText,
  telegramId: $('Webhook from ManyChat').item.json.body.telegram_id,
  username: $('Webhook from ManyChat').item.json.body.username,
  budget: $('Webhook from ManyChat').item.json.body.max_price,
  district: $('Webhook from ManyChat').item.json.body.district
};
